#!/usr/bin/env python3
"""Generate 20 lexical supplement clauses (lexical_031 ~ lexical_050)."""
import json

# Common retail tools
def retail_tools_stripped(tools_list):
    """Return stripped_tool_desc for retail."""
    mapping = {
        "get_user_details": {
            "type": "function",
            "function": {
                "name": "get_user_details",
                "description": "Get details of a user including profile, order history, and payment methods.",
                "parameters": {
                    "type": "object",
                    "properties": {"user_id": {"type": "string", "description": "The user ID to look up"}},
                    "required": ["user_id"]
                }
            }
        },
        "get_order_details": {
            "type": "function",
            "function": {
                "name": "get_order_details",
                "description": "Get details of a specific order including status, items, payment method, and timestamps.",
                "parameters": {
                    "type": "object",
                    "properties": {"order_id": {"type": "string", "description": "The order ID to look up"}},
                    "required": ["order_id"]
                }
            }
        },
        "cancel_pending_order": {
            "type": "function",
            "function": {
                "name": "cancel_pending_order",
                "description": "Cancel a pending order with the given reason. Returns updated order status.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "order_id": {"type": "string", "description": "The order ID to cancel"},
                        "reason": {"type": "string", "description": "The reason for cancellation"}
                    },
                    "required": ["order_id", "reason"]
                }
            }
        },
        "modify_pending_order_items": {
            "type": "function",
            "function": {
                "name": "modify_pending_order_items",
                "description": "Modify items in a pending order. Can change quantities or swap items.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "order_id": {"type": "string", "description": "The order ID"},
                        "item_ids": {"type": "array", "items": {"type": "string"}, "description": "Item IDs to modify"},
                        "new_item_ids": {"type": "array", "items": {"type": "string"}, "description": "Replacement item IDs"}
                    },
                    "required": ["order_id", "item_ids", "new_item_ids"]
                }
            }
        },
        "modify_pending_order_payment": {
            "type": "function",
            "function": {
                "name": "modify_pending_order_payment",
                "description": "Change the payment method of a pending order.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "order_id": {"type": "string", "description": "The order ID"},
                        "payment_method_id": {"type": "string", "description": "New payment method ID"}
                    },
                    "required": ["order_id", "payment_method_id"]
                }
            }
        },
        "return_delivered_order_items": {
            "type": "function",
            "function": {
                "name": "return_delivered_order_items",
                "description": "Initiate a return for items from a delivered order.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "order_id": {"type": "string", "description": "The order ID"},
                        "item_ids": {"type": "array", "items": {"type": "string"}, "description": "Item IDs to return"},
                        "payment_method_id": {"type": "string", "description": "Payment method for refund"}
                    },
                    "required": ["order_id", "item_ids", "payment_method_id"]
                }
            }
        },
        "exchange_delivered_order_items": {
            "type": "function",
            "function": {
                "name": "exchange_delivered_order_items",
                "description": "Exchange items from a delivered order for different items.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "order_id": {"type": "string", "description": "The order ID"},
                        "item_ids": {"type": "array", "items": {"type": "string"}, "description": "Item IDs to exchange"},
                        "new_item_ids": {"type": "array", "items": {"type": "string"}, "description": "Replacement item IDs"},
                        "payment_method_id": {"type": "string", "description": "Payment method for price difference"}
                    },
                    "required": ["order_id", "item_ids", "new_item_ids", "payment_method_id"]
                }
            }
        },
        "get_product_details": {
            "type": "function",
            "function": {
                "name": "get_product_details",
                "description": "Get details of a product including price, availability, and description.",
                "parameters": {
                    "type": "object",
                    "properties": {"product_id": {"type": "string", "description": "The product ID to look up"}},
                    "required": ["product_id"]
                }
            }
        }
    }
    return [mapping[t] for t in tools_list]

def retail_tools_full(tools_list):
    """Return full tools for retail (with richer descriptions)."""
    mapping = {
        "get_user_details": {
            "type": "function",
            "function": {
                "name": "get_user_details",
                "description": "Get details of a user including profile, order history, and payment methods. Use this to verify user identity and check account information before performing actions.",
                "parameters": {
                    "type": "object",
                    "properties": {"user_id": {"type": "string", "description": "The user ID to look up"}},
                    "required": ["user_id"]
                }
