                    "required": ["order_id", "reason"]
                }
            }
        },
        "modify_pending_order_items": {
            "type": "function",
            "function": {
                "name": "modify_pending_order_items",
                "description": "Modify items in a pending order. This action can only be performed once per order. After modification, the order status changes to 'pending (items modified)' and no further modifications or cancellations are possible.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "order_id": {"type": "string", "description": "The order ID"},
                        "item_ids": {"type": "array", "items": {"type": "string"}, "description": "Item IDs to modify"},
