            }
        },
        "return_delivered_order_items": {
            "type": "function",
            "function": {
                "name": "return_delivered_order_items",
                "description": "Initiate a return for items from a delivered order. The order must be in 'delivered' status. Refund is processed to the specified payment method.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "order_id": {"type": "string", "description": "The order ID"},
                        "item_ids": {"type": "array", "items": {"type": "string"}, "description": "Item IDs to return"},
                        "payment_method_id": {"type": "string", "description": "Payment method for refund"}
                    },
                    "required": ["order_id", "item_ids", "payment_method_id"]
                }
            }
        },
        "exchange_delivered_order_items": {
            "type": "function",
            "function": {
                "name": "exchange_delivered_order_items",
                "description": "Exchange items from a delivered order for different items. The order must be in 'delivered' status. Price differences are charged or refunded to the specified payment method.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "order_id": {"type": "string", "description": "The order ID"},
                        "item_ids": {"type": "array", "items": {"type": "string"}, "description": "Item IDs to exchange"},
                        "new_item_ids": {"type": "array", "items": {"type": "string"}, "description": "Replacement item IDs"},
                        "payment_method_id": {"type": "string", "description": "Payment method for price difference"}
                    },
                    "required": ["order_id", "item_ids", "new_item_ids", "payment_method_id"]
                }
            }
        },
        "get_product_details": {
            "type": "function",
            "function": {
                "name": "get_product_details",
                "description": "Get details of a product including price, availability, and description. Use this to check product information before exchanges or modifications.",
                "parameters": {
                    "type": "object",
                    "properties": {"product_id": {"type": "string", "description": "The product ID to look up"}},
                    "required": ["product_id"]
                }
            }
        }
    }
    return [mapping[t] for t in tools_list]

